void DEFP( UTTRST, uttrst, ASTERDOUBLE *t_rst ) {
    ASTERDOUBLE t_csm[3], t_lim;
    CALL_UTTCSM( t_csm );
    t_lim = get_tpmax();
    *t_rst = t_lim - t_csm[2];
}

